import numpy as np

def is_inverse(A, B):
    A = np.array(A, dtype=float)
    B = np.array(B, dtype=float)
    n = len(A)
    return np.allclose(B @ A, np.eye(n))

import numpy as np

def safe_hedge(greeks, target):
    A = np.array(greeks, dtype=float)
    b = np.array(target, dtype=float)
    # raise np.linalg.LinAlgError when A is singular
    if np.linalg.matrix_rank(A) < len(A):
        raise np.linalg.LinAlgError("singular matrix: no unique hedge")
    return np.linalg.solve(A, b)
